/**
 * @responsibility Pure file-kind detection and size formatting for FilePreview.
 * No React here so the logic stays unit-testable and reusable outside the DOM.
 */

/**
 * The preview strategies FilePreview ships with. Consumers can register
 * renderers for additional kinds (e.g. "video") without widening this union;
 * the renderer map accepts arbitrary string keys.
 */
export type FilePreviewKind = "image" | "pdf" | "unknown"

/** A file source described by URL plus optional display metadata. */
export interface FilePreviewFile {
  /** URL of the file contents — remote, data:, or an object URL. */
  src: string
  /** Display name; also feeds extension-based kind detection. */
  name?: string
  /** MIME type; when present it wins over any extension. */
  mimeType?: string
  /** Size in bytes, shown formatted in the header. */
  size?: number
}

/** Extensions treated as images, lowercase without the dot. */
export const filePreviewImageExtensions: readonly string[] = [
  "apng",
  "avif",
  "bmp",
  "gif",
  "ico",
  "jpeg",
  "jpg",
  "png",
  "svg",
  "webp",
]

/** Extensions treated as PDFs, lowercase without the dot. */
export const filePreviewPdfExtensions: readonly string[] = ["pdf"]

function kindFromMimeType(mimeType: string): FilePreviewKind {
  // Strip parameters ("application/pdf; version=1.7") before matching.
  const normalized = mimeType.split(";", 1)[0].trim().toLowerCase()
  if (normalized.startsWith("image/")) return "image"
  if (normalized === "application/pdf") return "pdf"
  return "unknown"
}

function mimeTypeOfDataUrl(src: string): string | null {
  const match = src.match(/^data:([^;,]*)/i)
  return match ? match[1] : null
}

function extensionOf(value: string): string | null {
  // Strip query and hash so "photo.jpg?w=200#top" resolves to "jpg".
  const path = value.split(/[?#]/, 1)[0]
  const segment = path.split("/").pop() ?? ""
  const dot = segment.lastIndexOf(".")
  if (dot <= 0 || dot === segment.length - 1) return null
  return segment.slice(dot + 1).toLowerCase()
}

function kindFromExtension(extension: string): FilePreviewKind {
  if (filePreviewImageExtensions.includes(extension)) return "image"
  if (filePreviewPdfExtensions.includes(extension)) return "pdf"
  return "unknown"
}

/**
 * Resolves the preview kind for a file. The MIME type wins when it names a
 * known kind; generic types like application/octet-stream fall through to the
 * extension of the name, then of the src pathname.
 */
export function detectFileKind(input: {
  mimeType?: string
  name?: string
  src?: string
}): FilePreviewKind {
  if (input.mimeType) {
    const kind = kindFromMimeType(input.mimeType)
    if (kind !== "unknown") return kind
  }
  // A data: URL carries its media type inline; its payload can contain dots,
  // so it must never reach the extension path.
  if (input.src?.startsWith("data:")) {
    const mediaType = mimeTypeOfDataUrl(input.src)
    return mediaType ? kindFromMimeType(mediaType) : "unknown"
  }
  for (const candidate of [input.name, input.src]) {
    if (!candidate) continue
    const extension = extensionOf(candidate)
    if (!extension) continue
    const kind = kindFromExtension(extension)
    if (kind !== "unknown") return kind
  }
  return "unknown"
}

const fileSizeUnits = ["B", "KB", "MB", "GB", "TB"] as const

/** Formats a byte count for display, e.g. 1_234_567 → "1.2 MB". */
export function formatFileSize(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 0) return ""
  let value = bytes
  let unit = 0
  // Compare the rounded value so 999_999 bumps to "1.0 MB", not "1000 KB".
  while (Math.round(value) >= 1000 && unit < fileSizeUnits.length - 1) {
    value /= 1000
    unit += 1
  }
  if (unit === 0) return `${Math.round(value)} ${fileSizeUnits[0]}`
  const oneDecimal = value.toFixed(1)
  const rounded =
    Number(oneDecimal) >= 10 ? String(Math.round(value)) : oneDecimal
  return `${rounded} ${fileSizeUnits[unit]}`
}

"use client"

/** @responsibility Shared context wiring for the FilePreview compound parts. */

import * as React from "react"

import type { FilePreviewFile, FilePreviewKind } from "./file-kind"

/** Props every renderer receives from FilePreviewContent. */
export interface FilePreviewRendererProps {
  file: FilePreviewFile
  kind: FilePreviewKind
}

/** A preview strategy for one file kind. */
export type FilePreviewRenderer = React.ComponentType<FilePreviewRendererProps>

/**
 * Maps file kinds to renderers. Keys beyond the built-in union are allowed so
 * consumers can register new kinds (paired with a custom `kind` prop) without
 * a library change.
 */
export type FilePreviewRendererMap = Partial<
  Record<FilePreviewKind | (string & {}), FilePreviewRenderer>
>

export interface FilePreviewContextValue {
  /** The resolved file, after any blob has become an object URL. Null while a blob's URL is still being created. */
  file: FilePreviewFile | null
  kind: FilePreviewKind | (string & {})
  /** The renderer resolved for `kind`, already falling back for unknown kinds. */
  renderer: FilePreviewRenderer
  onDownload?: (file: FilePreviewFile) => void
}

export const FilePreviewContext =
  React.createContext<FilePreviewContextValue | null>(null)

export function useFilePreviewContext(
  consumer: string,
): FilePreviewContextValue {
  const context = React.useContext(FilePreviewContext)
  if (!context) {
    throw new Error(`${consumer} must be rendered inside a FilePreview.`)
  }
  return context
}

"use client"

/** @responsibility The FilePreview root and chrome: resolves the file source and kind, picks the renderer from the registry, and provides Header/Content compound parts. */

import * as React from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  detectFileKind,
  formatFileSize,
  type FilePreviewFile,
  type FilePreviewKind,
} from "./file-kind"
import {
  FilePreviewContext,
  useFilePreviewContext,
  type FilePreviewContextValue,
  type FilePreviewRendererMap,
} from "./file-preview-context"
import { FilePreviewFallback } from "./file-preview-fallback"

// FilePreviewFallback spreads extra props onto its div, so it cannot serve as
// a renderer directly — the renderer contract's `kind` prop would land on the
// DOM as a bogus attribute.
const fallbackRenderer = ({ file }: { file: FilePreviewFile }) => (
  <FilePreviewFallback file={file} />
)
import { defaultFilePreviewRenderers } from "./file-preview-renderers"

export interface FilePreviewProps extends React.ComponentProps<"div"> {
  /** The file to preview, described by URL plus optional metadata. Exactly one of `file` and `blob` must be set. */
  file?: FilePreviewFile
  /** A File or Blob to preview; an object URL is created and revoked internally. */
  blob?: File | Blob
  /** Overrides kind detection — required when registering renderers for custom kinds. */
  kind?: FilePreviewKind | (string & {})
  /** Extra or replacement renderers, merged over the built-in registry. */
  renderers?: FilePreviewRendererMap
  /** Called when the download link is activated. */
  onDownload?: (file: FilePreviewFile) => void
}

function useObjectUrl(blob: File | Blob | undefined): string | null {
  const [entry, setEntry] = React.useState<{
    blob: File | Blob
    url: string
  } | null>(null)
  React.useEffect(() => {
    if (!blob) {
      setEntry(null)
      return
    }
    const url = URL.createObjectURL(blob)
    setEntry({ blob, url })
    return () => URL.revokeObjectURL(url)
  }, [blob])
  // On a blob swap the state still holds the previous blob's (soon revoked)
  // URL for one render; report null so that frame shows the skeleton instead
  // of pairing the new blob's metadata with the old image.
  return entry && entry.blob === blob ? entry.url : null
}

function FilePreview({
  file: fileProp,
  blob,
  kind: kindProp,
  renderers,
  onDownload,
  className,
  children,
  ...props
}: FilePreviewProps) {
  if (process.env.NODE_ENV !== "production") {
    if ((fileProp && blob) || (!fileProp && !blob)) {
      console.warn("FilePreview expects exactly one of `file` or `blob`.")
    }
  }

  const objectUrl = useObjectUrl(blob)
  const file = React.useMemo<FilePreviewFile | null>(() => {
    if (fileProp) return fileProp
    if (blob && objectUrl) {
      return {
        src: objectUrl,
        name: blob instanceof File ? blob.name : undefined,
        mimeType: blob.type || undefined,
        size: blob.size,
      }
    }
    return null
  }, [fileProp, blob, objectUrl])

  const kind = kindProp ?? (file ? detectFileKind(file) : "unknown")
  const mergedRenderers = React.useMemo(
    () => ({ ...defaultFilePreviewRenderers, ...renderers }),
    [renderers],
  )
  const renderer = mergedRenderers[kind] ?? fallbackRenderer

  const contextValue = React.useMemo<FilePreviewContextValue>(
    () => ({ file, kind, renderer, onDownload }),
    [file, kind, renderer, onDownload],
  )

  return (
    <FilePreviewContext.Provider value={contextValue}>
      <div
        data-slot="file-preview"
        data-kind={kind}
        role="group"
        aria-label={file?.name ?? "File preview"}
        className={cn(
          "flex h-full min-h-0 w-full flex-col overflow-hidden rounded-xl border border-border bg-card text-card-foreground",
          className,
        )}
        {...props}
      >
        {children ?? (
          <>
            <FilePreviewHeader />
            <FilePreviewContent />
          </>
        )}
      </div>
    </FilePreviewContext.Provider>
  )
}

export interface FilePreviewHeaderProps extends React.ComponentProps<"div"> {}

/** File name, formatted size, and a download link. Renders its children after the name block for extra actions. */
function FilePreviewHeader({
  className,
  children,
  ...props
}: FilePreviewHeaderProps) {
  const { file, onDownload } = useFilePreviewContext("FilePreviewHeader")
  return (
    <div
      data-slot="file-preview-header"
      className={cn(
        "flex shrink-0 items-center gap-2 border-b border-border px-3 py-2",
        className,
      )}
      {...props}
    >
      <div className="flex min-w-0 flex-1 flex-col">
        <span className="nessa-text-3 truncate font-medium text-foreground">
          {file?.name ?? "Untitled file"}
        </span>
        {file?.size !== undefined ? (
          <span className="nessa-text-1 text-muted-foreground">
            {formatFileSize(file.size)}
          </span>
        ) : null}
      </div>
      {children}
      {file ? (
        <a
          href={file.src}
          download={file.name}
          aria-label={`Download ${file.name ?? "file"}`}
          onClick={() => onDownload?.(file)}
          className="inline-flex size-8 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
        >
          <Download aria-hidden="true" className="size-4" />
        </a>
      ) : null}
    </div>
  )
}

export interface FilePreviewContentProps extends React.ComponentProps<"div"> {}

/** Hosts the renderer resolved for the file's kind. */
function FilePreviewContent({
  className,
  children,
  ...props
}: FilePreviewContentProps) {
  const { file, kind, renderer: Renderer } =
    useFilePreviewContext("FilePreviewContent")
  return (
    <div
      data-slot="file-preview-content"
      aria-busy={!children && !file ? true : undefined}
      className={cn("min-h-0 flex-1 overflow-hidden", className)}
      {...props}
    >
      {children ??
        (file ? (
          <Renderer file={file} kind={kind as FilePreviewKind} />
        ) : (
          <div
            aria-hidden="true"
            className="h-full w-full animate-pulse bg-muted/50"
          />
        ))}
    </div>
  )
}

export { FilePreview, FilePreviewContent, FilePreviewHeader }

"use client"

/** @responsibility The FilePreview fallback surface: shown for unknown kinds and renderer failures, always keeping the file reachable via a download link. */

import * as React from "react"
import { Download, FileQuestion } from "lucide-react"

import { cn } from "@/lib/utils"
import type { FilePreviewFile } from "./file-kind"
import { useFilePreviewContext } from "./file-preview-context"

export interface FilePreviewFallbackProps extends React.ComponentProps<"div"> {
  /** Overrides the file from context; lets renderers reuse the fallback for their own error states. */
  file?: FilePreviewFile
  /** Message shown under the file name. Defaults to "No preview available". */
  message?: string
}

function FilePreviewFallback({
  file: fileProp,
  message = "No preview available",
  className,
  children,
  ...props
}: FilePreviewFallbackProps) {
  const context = useFilePreviewContext("FilePreviewFallback")
  const file = fileProp ?? context.file
  return (
    <div
      data-slot="file-preview-fallback"
      className={cn(
        "flex h-full w-full flex-col items-center justify-center gap-2 p-6 text-center",
        className,
      )}
      {...props}
    >
      <FileQuestion
        aria-hidden="true"
        className="size-8 text-muted-foreground"
      />
      {file?.name ? (
        <span className="nessa-text-3 max-w-full truncate font-medium text-foreground">
          {file.name}
        </span>
      ) : null}
      <span className="nessa-text-2 text-muted-foreground">{message}</span>
      {file ? (
        <a
          href={file.src}
          download={file.name}
          onClick={() => context.onDownload?.(file)}
          className="nessa-text-2 inline-flex min-h-6 items-center gap-1 rounded-md px-2 py-1 font-medium text-foreground underline underline-offset-2 hover:bg-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
        >
          <Download aria-hidden="true" className="size-3.5" />
          Download
        </a>
      ) : null}
      {children}
    </div>
  )
}

export { FilePreviewFallback }

"use client"

/** @responsibility The image preview strategy: renders every image type through a plain img element with loading and error states. */

import * as React from "react"

import { cn } from "@/lib/utils"
import { FilePreviewFallback } from "./file-preview-fallback"
import type { FilePreviewRendererProps } from "./file-preview-context"

/**
 * Previews all image types with a plain img element, which keeps SVG sources
 * script-inert. Shows a pulse skeleton while loading and the fallback when
 * the source fails to decode.
 */
function FilePreviewImage({ file }: FilePreviewRendererProps) {
  const [status, setStatus] = React.useState<"loading" | "loaded" | "error">(
    "loading",
  )
  // Reset per src so a swapped file goes back through the loading state.
  React.useEffect(() => setStatus("loading"), [file.src])
  // A cached or instantly failing source can settle before React attaches the
  // load/error listeners, so read the element's own state on mount too.
  const readSettledState = React.useCallback((node: HTMLImageElement | null) => {
    if (node?.complete) setStatus(node.naturalWidth > 0 ? "loaded" : "error")
  }, [])

  if (status === "error") {
    return <FilePreviewFallback message="Image failed to load" />
  }
  return (
    <div
      data-slot="file-preview-image"
      aria-busy={status === "loading" || undefined}
      className="relative flex h-full w-full items-center justify-center overflow-hidden"
    >
      {status === "loading" ? (
        <div
          data-slot="file-preview-image-skeleton"
          aria-hidden="true"
          className="absolute inset-4 animate-pulse rounded-lg bg-muted"
        />
      ) : null}
      <img
        ref={readSettledState}
        src={file.src}
        alt={file.name ?? "Image preview"}
        draggable={false}
        onLoad={() => setStatus("loaded")}
        onError={() => setStatus("error")}
        className={cn(
          "max-h-full max-w-full object-contain",
          status === "loading" && "opacity-0",
        )}
      />
    </div>
  )
}

export { FilePreviewImage }

"use client"

/** @responsibility The PDF preview strategy: delegates rendering to the browser's built-in viewer with a download fallback. */

import * as React from "react"

import { FilePreviewFallback } from "./file-preview-fallback"
import type { FilePreviewRendererProps } from "./file-preview-context"

/**
 * Previews PDFs through the browser's built-in viewer via an object embed —
 * no PDF library. Chromium, WebView2, and WKWebView all render inline;
 * environments without an inline viewer (e.g. iOS Safari) get the object's
 * fallback children instead. Consumers needing full viewer control can swap
 * in their own renderer (e.g. pdf.js-based) through the `renderers` prop.
 */
function FilePreviewPdf({ file }: FilePreviewRendererProps) {
  return (
    <object
      data-slot="file-preview-pdf"
      data={file.src}
      type="application/pdf"
      aria-label={file.name ?? "PDF document"}
      className="h-full w-full"
    >
      <FilePreviewFallback message="This browser cannot preview PDFs inline" />
    </object>
  )
}

export { FilePreviewPdf }

"use client"

/** @responsibility The built-in kind→renderer registry. Each strategy lives in its own module; this file only assembles the default map. */

import { FilePreviewImage } from "./file-preview-image"
import { FilePreviewPdf } from "./file-preview-pdf"
import type { FilePreviewRendererMap } from "./file-preview-context"

/**
 * FilePreview merges consumer-provided renderers over this map, so entries
 * can be overridden or extended per use without touching the library.
 */
export const defaultFilePreviewRenderers: FilePreviewRendererMap = {
  image: FilePreviewImage,
  pdf: FilePreviewPdf,
}
